int main(){const u64Int n=16384;std::vector<u64Int>want(n),out(n);for(u64Int i=0;i<n;i++)want[i]=i;u64Int rng=1;for(u64Int i=0;i<4*n;i++){rng=(rng<<1)^((s64Int)rng<0?POLY:0);want[rng&(n-1)]^=rng;}u64Int*table;cudaMalloc(&table,n*8);auto run=[&](){initTable<<<64,256>>>(table,n);update<<<1,128>>>(table,n);};run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;for(int trial=1;trial<=5;trial++){auto t=std::chrono::steady_clock::now();for(int k=0;k<10;k++)run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/10;cudaMemcpy(out.data(),table,n*8,cudaMemcpyDeviceToHost);bool ok=out==want;char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),8,n,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%llu,\"max_abs_error\":%d,\"timing_region\":\"mean_init_plus_random_atomic_updates\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%llu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",n,ok?0:1,path,n);if(!ok)return 1;}cudaFree(table);}
